uv run python -c 'import csv,json,re,hashlib,xml.etree.ElementTree as ET; from pathlib import Path; from html.parser import HTMLParser; from statistics import mean; root=Path.cwd(); source=(root/"data/shoes.md").read_text(); result=json.loads((root/"data/analysis.json").read_text()); blocks=re.findall(r"^### \*\*(.+?)\*\*\s*(.*?)(?=^### \*\*|\Z)",source,re.M|re.S); expected={name:[int(x) for x in re.findall(r"Rating: (\d)/5",body)] for name,body in blocks}; assert len(expected)==6 and sum(map(len,expected.values()))==24; assert result["source_sha256"]==hashlib.sha256((root/"data/shoes.md").read_bytes()).hexdigest(); all_ratings=[rating for ratings in expected.values() for rating in ratings]; assert sum(all_ratings)==88; assert result["overall"]["average_rating"]==mean(all_ratings); assert result["overall"]["positive_count"]==16 and result["overall"]["low_count"]==6 and result["overall"]["neutral_count"]==2; review_rows=list(csv.DictReader((root/"data/reviews.csv").open())); assert len(review_rows)==24; summary_rows=list(csv.DictReader((root/"data/product_summary.csv").open())); assert len(summary_rows)==6; assert len({r["review_id"] for r in review_rows})==24; 
for product in result["products"]:
 ratings=expected[product["product"]]; assert product["average_rating"]==mean(ratings); assert product["positive_count"]==sum(r>=4 for r in ratings); assert product["low_count"]==sum(r<=2 for r in ratings); assert product["rank"]==1+sum(mean(other)>mean(ratings) for other in expected.values()); assert product["rating_distribution"]=={str(i):ratings.count(i) for i in range(1,6)}
for row,review in zip(review_rows,result["reviews"]):
 assert row["comment"]==review["comment"] and int(row["rating"])==review["rating"]; assert review["comment"] in source
for row,product in zip(summary_rows,result["products"]):
 assert row["product"]==product["product"] and float(row["average_rating"])==product["average_rating"]
class CheckHTML(HTMLParser):
 def __init__(self):
  super().__init__(); self.ids=[]; self.links=[]; self.stack=[]; self.text=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if "id" in a:self.ids.append(a["id"])
  if "href" in a:self.links.append(a["href"])
  assert "src" not in a, "Unexpected external resource"
  if tag not in {"meta","link","br","hr","img","input"}:self.stack.append(tag)
 def handle_endtag(self,tag):
  assert self.stack and self.stack.pop()==tag, f"Unbalanced {tag}"
 def handle_data(self,data):self.text.append(data)
html=(root/"reports/customer_satisfaction_report.html").read_text(); parser=CheckHTML(); parser.feed(html); parser.close(); assert not parser.stack; assert len(parser.ids)==len(set(parser.ids)); assert all(link.startswith("#") and link[1:] in parser.ids for link in parser.links); assert all(r["review_id"] in parser.ids for r in result["reviews"]); rendered="".join(parser.text); assert all(r["comment"] in rendered for r in result["reviews"]); svg=ET.parse(root/"reports/satisfaction_chart.svg").getroot(); assert svg.attrib["role"]=="img"; assert len(svg.findall("{http://www.w3.org/2000/svg}g/{http://www.w3.org/2000/svg}rect"))==6; assert (root/"reports/satisfaction_chart.svg").read_text() in html; print("PASS: source ratings, all product metrics and ranks, CSV exports, review fidelity, HTML nesting and links, and SVG chart.")'

